import{initial,act,reasons}from './engine.mjs';let s=initial();const $=id=>document.getElementById(id);const names={prior:'Trabajo existente revisado',gap:'Brecha específica',paid:'Fondos confirmados',scope:'Alcance fijo',supervisor:'Supervisor disponible',capacity:'Capacidad de revisión',criteria:'Criterios escritos',help:'Ayuda y escalación'};
function render(){const paused=s.status==='paused';$('status').textContent={ready:'Por iniciar',active:'En curso',paused:'Pausada',stopped:'Detenida'}[s.status];$('status').className='badge'+(paused?' paused':'');$('explain').textContent=paused?'No continúes ni envíes trabajo. La coordinadora debe resolver cada condición y reanudar explícitamente.':s.status==='stopped'?'La tarea terminó. No se puede reiniciar ni modificar; usa Reiniciar demo para otro escenario.':'Verifica las condiciones antes de trabajar.';$('reasons').replaceChildren(...reasons(s).map(t=>{const li=document.createElement('li');li.textContent=t;return li}));$('gates').replaceChildren(...Object.entries(names).map(([k,v])=>{let b=document.createElement('button');b.className='gate'+(!s[k]?' off':'');b.textContent=v+' · '+(s[k]?'Sí':'No');b.dataset.a='toggle:'+k;return b}));$('proof').textContent=s.proof+' · SIMULADO';$('progress').textContent=`Entrega: ${s.submitted?'enviada':'pendiente'} · Revisión: ${s.reviewed?'registrada':'pendiente'} · Pago recibido por Alex: ${s.workerPaid?'registrado (simulado)':'pendiente'}`;$('outcome').textContent=`Apertura: ${s.opened?'registrada (simulada)':'no registrada'} · Acción: ${s.decision}`;$('decision').value=s.decision;$('decision').disabled=!s.opened||s.status==='stopped';$('shadow').replaceChildren();if(s.repeat){let p=document.createElement('p');p.textContent=s.shadowApproved?'Revisión humana simulada registrada. Todas las demás condiciones siguen aplicando.':'Alerta: revisar si estas tareas sustituyen trabajo junior continuo.';$('shadow').append(p);for(const[a,t]of [['shadow-clear','Registrar revisión: tarea excepcional'],['shadow-stop','Detener y derivar a empleo formal']]){let b=document.createElement('button');b.className='secondary';b.dataset.a=a;b.textContent=t;$('shadow').append(b)}}$('log').replaceChildren(...s.log.slice().reverse().map(e=>{let li=document.createElement('li');li.textContent=`${e.time.slice(11,19)} · ${e.event} → ${e.status}`;return li}));document.querySelectorAll('[data-a]').forEach(b=>{const a=b.dataset.a;b.disabled=s.status==='stopped'&&a!=='reset'||a==='submit'&&s.status!=='active'||a==='review'&&(!s.submitted||s.status!=='active')||a==='walkthrough'&&(!s.reviewed||s.status!=='active')||a==='worker-pay'&&!s.reviewed||a==='resume'&&s.status!=='paused'||a==='start'&&s.status!=='ready'})}
document.addEventListener('click',e=>{const b=e.target.closest('[data-a]');if(b&&!b.disabled){s=act(s,b.dataset.a);render()}});$('decision').addEventListener('change',e=>{s=act(s,'decision:'+e.target.value);render()});render();
